insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('日傘をさす女性（モネ夫人と息子）', 'Woman with a Parasol – Madame Monet and Her Son', 'クロード・モネ', 'Claude Monet',
        1875,
        (select slug from public.art_movements where slug = 'impressionism'),
        'ナショナル・ギャラリー・オブ・アート', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Claude_Monet_-_Woman_with_a_Parasol_-_Madame_Monet_and_Her_Son_-_Google_Art_Project.jpg/960px-Claude_Monet_-_Woman_with_a_Parasol_-_Madame_Monet_and_Her_Son_-_Google_Art_Project.jpg', '風の吹く丘の上で日傘をさす妻カミーユと息子ジャンを、見上げる角度から描いた作品です。すばやい筆で雲や草のゆれが表され、白いドレスには空の青や草の緑が映り込んでいます。人物を描きながらも、主役は光と風そのものだといえます。輪郭より光の移ろいを重んじる印象派の考え方がよく分かる一点です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

