insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('雪舟', 'Sesshū Tōyō', '雪舟',
        1420, 1506, 'japan', array['suiboku']::text[],
        '室町時代の禅僧で、日本の水墨画を大成した画家です。', '備中（いまの岡山県）に生まれ、京都の相国寺で禅の修行をしながら絵を学びました。周文に学んだのち、山口の大内氏のもとに移ります。

1467年ごろ明（中国）に渡り、現地の山水画と実際の風景にふれて帰国しました。輪郭を力強い線で描く画風を確立し、中国の手本をなぞるだけではない、日本の水墨画を生みました。

代表作の「四季山水図（山水長巻）」は、15メートルをこえる画面に四季の移り変わりを描いています。筆の勢いと、余白の取り方に注目してみてください。', 'https://ja.wikipedia.org/wiki/%E9%9B%AA%E8%88%9F')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('レオナルド・ダ・ヴィンチ', 'Leonardo da Vinci', 'ダ・ヴィンチ',
        1452, 1519, 'west', array['renaissance']::text[],
        '盛期ルネサンスを代表するイタリアの画家で、科学や工学にも通じた「万能の人」です。', 'フィレンツェ近郊のヴィンチ村に生まれ、ヴェロッキオの工房で修業しました。ミラノ、フィレンツェ、ローマを経て、晩年はフランス王フランソワ1世に招かれてフランスで亡くなりました。

輪郭線をぼかして柔らかな陰影をつける「スフマート」や、遠くのものほど青く淡くする空気遠近法を用い、人物と風景を一つの空気の中に溶け込ませました。

完成した絵は多くありませんが、「モナ・リザ」や「最後の晩餐」は後の画家たちの手本になりました。解剖学や機械の研究を書きとめた手稿も残っています。', 'https://ja.wikipedia.org/wiki/%E3%83%AC%E3%82%AA%E3%83%8A%E3%83%AB%E3%83%89%E3%83%BB%E3%83%80%E3%83%BB%E3%83%B4%E3%82%A3%E3%83%B3%E3%83%81')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('サンドロ・ボッティチェッリ', 'Sandro Botticelli', 'ボッティチェッリ',
        1445, 1510, 'west', array['renaissance']::text[],
        '初期ルネサンスのフィレンツェで活躍し、優美な線で神話を描いた画家です。', 'フィレンツェに生まれ、フィリッポ・リッピに学びました。メディチ家とその周辺の人々の注文を受け、システィーナ礼拝堂の壁画制作にも加わっています。

キリスト教の主題が中心だった時代に、「ヴィーナスの誕生」や「春（プリマヴェーラ）」のような古代神話の大画面を描きました。流れるような輪郭線と、装飾的な美しさが特徴です。

晩年は修道士サヴォナローラの影響を受け、宗教的で厳しい作風に変わったといわれます。', 'https://ja.wikipedia.org/wiki/%E3%82%B5%E3%83%B3%E3%83%89%E3%83%AD%E3%83%BB%E3%83%9C%E3%83%83%E3%83%86%E3%82%A3%E3%83%81%E3%82%A7%E3%83%83%E3%83%AA')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ラファエロ・サンツィオ', 'Raphael', 'ラファエロ',
        1483, 1520, 'west', array['renaissance']::text[],
        '調和のとれた構図と穏やかな人物表現で、盛期ルネサンスの理想を示した画家です。', 'ウルビーノに生まれ、ペルジーノの工房で学びました。フィレンツェでレオナルドやミケランジェロの作品にふれ、のちにローマで教皇の仕事を任されます。

ヴァチカン宮殿の「アテナイの学堂」では、古代の哲学者たちを壮大な建築の中に整然と配置しました。聖母子像も多く描き、その穏やかな表情は長く手本とされました。

37歳で亡くなりましたが、後のアカデミーでは「最も完成された画家」として学ばれ続けました。', 'https://ja.wikipedia.org/wiki/%E3%83%A9%E3%83%95%E3%82%A1%E3%82%A8%E3%83%AD%E3%83%BB%E3%82%B5%E3%83%B3%E3%83%84%E3%82%A3%E3%82%AA')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アルブレヒト・デューラー', 'Albrecht Dürer', 'デューラー',
        1471, 1528, 'west', array['renaissance']::text[],
        'ドイツ・ルネサンスを代表する画家・版画家です。', 'ニュルンベルクに金細工師の子として生まれました。二度イタリアを訪れ、遠近法や人体の比例を学んで、北方の細密な描写と結びつけました。

木版画や銅版画で特に名高く、「メレンコリアI」や「騎士と死と悪魔」などの版画は、印刷によってヨーロッパ中に広まりました。

自画像を何点も残しており、画家を職人ではなく知的な芸術家として示そうとした姿勢がうかがえます。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%AB%E3%83%96%E3%83%AC%E3%83%92%E3%83%88%E3%83%BB%E3%83%87%E3%83%A5%E3%83%BC%E3%83%A9%E3%83%BC')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('カラヴァッジョ', 'Caravaggio', 'カラヴァッジョ',
        1571, 1610, 'west', array['baroque']::text[],
        '強い明暗の対比と生々しい写実で、バロック絵画の扉を開いたイタリアの画家です。', '本名はミケランジェロ・メリージ。ミラノで修業し、ローマで聖堂の大きな注文を受けて一躍有名になりました。

暗い背景から人物を強い光で浮かび上がらせる描き方（テネブリズム）で、聖書の場面を目の前の出来事のように描きました。聖人を庶民の姿で描いたことは議論も呼びました。

その表現はヨーロッパ中の画家に広まり、「カラヴァジェスキ」と呼ばれる追随者を生みました。', 'https://ja.wikipedia.org/wiki/%E3%82%AB%E3%83%A9%E3%83%B4%E3%82%A1%E3%83%83%E3%82%B8%E3%83%A7')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ピーテル・パウル・ルーベンス', 'Peter Paul Rubens', 'ルーベンス',
        1577, 1640, 'west', array['baroque']::text[],
        '躍動する人体と豊かな色彩で、バロックの華やかさを体現したフランドルの画家です。', 'アントウェルペンを拠点に、大きな工房を率いて各国の王侯や教会の注文に応えました。外交官としても活躍しています。

うねるような構図、たっぷりとした肉体、温かい肌の色が特徴で、宗教画から神話画、肖像、風景まで幅広く描きました。

弟子のヴァン・ダイクをはじめ多くの画家に影響を与え、のちのロココの画家たちも彼の色彩を手本にしました。', 'https://ja.wikipedia.org/wiki/%E3%83%94%E3%83%BC%E3%83%86%E3%83%AB%E3%83%BB%E3%83%91%E3%82%A6%E3%83%AB%E3%83%BB%E3%83%AB%E3%83%BC%E3%83%99%E3%83%B3%E3%82%B9')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('レンブラント・ファン・レイン', 'Rembrandt', 'レンブラント',
        1606, 1669, 'west', array['baroque']::text[],
        '光と影で人の内面を描いた、オランダ黄金時代の画家です。', 'ライデンに生まれ、アムステルダムで肖像画家として成功しました。集団肖像画「夜警」はその代表作です。

暗がりの中に光を当てる描き方で、人物の表情や心の動きを深く表しました。若いころから晩年まで描き続けた多くの自画像には、年を重ねる自分の姿が率直に残っています。

版画（エッチング）でも優れた作品を残しました。晩年は経済的に苦しみましたが、表現はいっそう深まっていきました。', 'https://ja.wikipedia.org/wiki/%E3%83%AC%E3%83%B3%E3%83%96%E3%83%A9%E3%83%B3%E3%83%88%E3%83%BB%E3%83%95%E3%82%A1%E3%83%B3%E3%83%BB%E3%83%AC%E3%82%A4%E3%83%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ヨハネス・フェルメール', 'Johannes Vermeer', 'フェルメール',
        1632, 1675, 'west', array['baroque']::text[],
        '静かな室内に差し込む光を描いた、オランダ・デルフトの画家です。', '生涯のほとんどをデルフトで過ごしました。確かな作品は30数点しか残っておらず、生涯についてもわかっていないことが多い画家です。

窓から入る柔らかな光、手紙を読む女性や楽器を奏でる人など、日常のひとときを落ち着いた構図で描きました。高価な天然ウルトラマリンの青も印象的です。

19世紀に再評価されるまで長く忘れられていましたが、いまでは世界中で愛される画家の一人です。', 'https://ja.wikipedia.org/wiki/%E3%83%A8%E3%83%8F%E3%83%8D%E3%82%B9%E3%83%BB%E3%83%95%E3%82%A7%E3%83%AB%E3%83%A1%E3%83%BC%E3%83%AB')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ディエゴ・ベラスケス', 'Diego Velázquez', 'ベラスケス',
        1599, 1660, 'west', array['baroque']::text[],
        'スペイン王フェリペ4世の宮廷画家として活躍した、スペイン黄金時代の画家です。', 'セビーリャに生まれ、若くしてマドリードの宮廷に招かれました。二度のイタリア旅行でティツィアーノらの作品を学んでいます。

近くで見ると素早い筆跡なのに、離れると布や光が本物のように見える描き方は、のちの印象派の画家たちを驚かせました。

代表作「ラス・メニーナス」は、見る人の位置まで画面に取り込んだような不思議な構図で、今も多くの解釈を生んでいます。', 'https://ja.wikipedia.org/wiki/%E3%83%87%E3%82%A3%E3%82%A8%E3%82%B4%E3%83%BB%E3%83%99%E3%83%A9%E3%82%B9%E3%82%B1%E3%82%B9')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('俵屋宗達', 'Tawaraya Sōtatsu', '宗達',
        null, null, 'japan', array['rinpa']::text[],
        '江戸時代初期の京都で活躍し、のちに「琳派」と呼ばれる流れの出発点となった画家です。', '生没年は分かっていません。京都で「俵屋」という絵屋を営んでいたと考えられ、本阿弥光悦と組んだ書と絵の合作でも知られます。

金や銀の地に、たらし込み（乾かないうちに別の色をにじませる技法）を使った大胆な構図で、平安時代の大和絵を新しくよみがえらせました。

「風神雷神図屏風」は、のちに尾形光琳や酒井抱一が模写し、琳派が時代をこえて受け継がれるきっかけになりました。', 'https://ja.wikipedia.org/wiki/%E4%BF%B5%E5%B1%8B%E5%AE%97%E9%81%94')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('尾形光琳', 'Ogata Kōrin', '光琳',
        1658, 1716, 'japan', array['rinpa']::text[],
        '宗達の画風に学び、意匠性の高い画面で琳派を大成した江戸時代中期の画家です。', '京都の呉服商「雁金屋」に生まれ、豊かな環境で能や書、工芸に親しみました。家業が傾いたのち、本格的に絵の道に進みます。

「燕子花図屏風」では、金地にカキツバタの群れだけをリズミカルに並べ、物語の場面を描かずに『伊勢物語』を思わせました。弟の尾形乾山と組んだ陶器の絵付けも残しています。

単純化した形とくり返しの美しさは「光琳模様」として着物などにも広まり、近代のデザインにも影響を与えました。', 'https://ja.wikipedia.org/wiki/%E5%B0%BE%E5%BD%A2%E5%85%89%E7%90%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('葛飾北斎', 'Katsushika Hokusai', '北斎',
        1760, 1849, 'japan', array['ukiyo-e']::text[],
        '風景版画から絵本まで、90年近い生涯で膨大な作品を残した江戸時代の浮世絵師です。', '江戸の本所に生まれ、勝川春章に入門しました。生涯に30回以上も画号を変え、90回以上引っ越したといわれます。

70歳を過ぎて刊行した「冨嶽三十六景」で、富士山をさまざまな場所と季節から描き、風景画を浮世絵の大きなジャンルにしました。絵手本「北斎漫画」も広く読まれました。

19世紀後半にヨーロッパへ紹介されると、モネやゴッホ、ドビュッシーらに強い影響を与え、ジャポニスムの象徴となりました。', 'https://ja.wikipedia.org/wiki/%E8%91%9B%E9%A3%BE%E5%8C%97%E6%96%8E')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('歌川広重', 'Utagawa Hiroshige', '広重',
        1797, 1858, 'japan', array['ukiyo-e']::text[],
        '旅情あふれる風景版画で人気を集めた、江戸時代後期の浮世絵師です。', '江戸の定火消（ひけし）同心の家に生まれ、歌川豊広に入門しました。

「東海道五拾三次」で風景画家としての名声を得て、晩年には「名所江戸百景」を手がけました。雨や雪、夕暮れなど、天気や時刻の空気をとらえるのが巧みです。

大胆に手前のものを大きく切り取る構図は、ゴッホが油彩で模写したことでも知られ、西洋の画家たちに新鮮な驚きを与えました。', 'https://ja.wikipedia.org/wiki/%E6%AD%8C%E5%B7%9D%E5%BA%83%E9%87%8D')
