insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フランシスコ・デ・ゴヤ', 'Francisco Goya', 'ゴヤ',
        1746, 1828, 'west', array['romanticism']::text[],
        '宮廷画家として成功しながら、戦争や人間の暗い面も見つめたスペインの画家です。', 'アラゴン地方に生まれ、タピスリーの下絵画家を経て、スペイン王室の首席宮廷画家になりました。

ナポレオン軍の侵攻を描いた「マドリード、1808年5月3日」や版画集「戦争の惨禍」で、名もない人々が受ける暴力をまっすぐに描きました。

晩年に自宅の壁に描いた「黒い絵」は、近代絵画の先駆けとして、のちの表現主義などにも通じる表現と見なされています。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%83%A9%E3%83%B3%E3%82%B7%E3%82%B9%E3%82%B3%E3%83%BB%E3%83%87%E3%83%BB%E3%82%B4%E3%83%A4')
