insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ウジェーヌ・ドラクロワ', 'Eugène Delacroix', 'ドラクロワ',
        1798, 1863, 'west', array['romanticism']::text[],
        '激しい感情と鮮やかな色彩で、フランス・ロマン主義を率いた画家です。', 'パリ近郊に生まれ、ジェリコーの影響を受けて歴史画で頭角をあらわしました。

線による正確さを重んじた新古典主義に対し、色と動きで感情を伝える絵を描きました。1830年の七月革命を描いた「民衆を導く自由の女神」はその代表作です。

モロッコへの旅で見た光と色は、のちの作品にも生かされました。補色を並べる色づかいは、印象派の画家たちにも学ばれました。', 'https://ja.wikipedia.org/wiki/%E3%82%A6%E3%82%B8%E3%82%A7%E3%83%BC%E3%83%8C%E3%83%BB%E3%83%89%E3%83%A9%E3%82%AF%E3%83%AD%E3%83%AF')
