    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジャン＝フランソワ・ミレー', 'Jean-François Millet', 'ミレー',
        1814, 1875, 'west', array['realism']::text[],
        '農民の暮らしと労働を、静かな尊厳とともに描いたフランスの画家です。', 'ノルマンディーの農家に生まれ、パリで学んだのち、バルビゾン村に移り住みました。

「落穂拾い」「晩鐘」など、働く農民の姿を大きく、落ち着いた色で描きました。理想化された神話や歴史ではなく、身近な現実を主題にした点で写実主義の流れに位置づけられます。

ゴッホはミレーを深く尊敬し、その作品を何点も模写しています。日本でも明治以降とくに親しまれてきました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A3%E3%83%B3%EF%BC%9D%E3%83%95%E3%83%A9%E3%83%B3%E3%82%BD%E3%83%AF%E3%83%BB%E3%83%9F%E3%83%AC%E3%83%BC')
