insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ギュスターヴ・クールベ', 'Gustave Courbet', 'クールベ',
        1819, 1877, 'west', array['realism']::text[],
        '「天使は見たことがないから描かない」と語ったとされる、写実主義の旗手です。', 'フランス東部のオルナンに生まれ、パリで独学に近い形で絵を学びました。

故郷の葬儀を巨大な画面に描いた「オルナンの埋葬」など、歴史画の大きさで普通の人々を描き、大きな論争を呼びました。1855年には万国博覧会の会場の外で自分の個展を開いています。

パリ・コミューンに参加したことで投獄され、晩年はスイスに亡命して亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%82%AE%E3%83%A5%E3%82%B9%E3%82%BF%E3%83%BC%E3%83%B4%E3%83%BB%E3%82%AF%E3%83%BC%E3%83%AB%E3%83%99')
