insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('エドゥアール・マネ', 'Édouard Manet', 'マネ',
        1832, 1883, 'west', array['impressionism']::text[],
        '伝統的な絵画の約束事を破り、近代絵画への道を開いたフランスの画家です。', 'パリの裕福な家庭に生まれ、ベラスケスやゴヤなどスペイン絵画に強く惹かれました。

「草上の昼食」や「オランピア」で、神話の衣を借りずに同時代の人物を描き、平らな色面と大胆な筆づかいで激しい非難を浴びました。

印象派展には参加しませんでしたが、モネら若い画家たちの精神的な中心となり、「印象派の父」とも呼ばれます。', 'https://ja.wikipedia.org/wiki/%E3%82%A8%E3%83%89%E3%82%A5%E3%82%A2%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%9E%E3%83%8D')
