    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('クロード・モネ', 'Claude Monet', 'モネ',
        1840, 1926, 'west', array['impressionism']::text[],
        '移ろう光を追い続けた、印象派を代表するフランスの画家です。', 'パリに生まれ、港町ル・アーヴルで育ちました。風景画家ブーダンに屋外で描くことを教わったのが出発点です。

1874年の第1回印象派展に出した「印象・日の出」が、印象派という名前のもとになりました。同じ積みわらや大聖堂を、時刻や季節を変えて描いた連作に、光への関心がよく表れています。

晩年はジヴェルニーの自宅の庭に日本風の橋をかけた池をつくり、睡蓮を描き続けました。浮世絵の収集家でもありました。', 'https://ja.wikipedia.org/wiki/%E3%82%AF%E3%83%AD%E3%83%BC%E3%83%89%E3%83%BB%E3%83%A2%E3%83%8D')
