    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ピエール＝オーギュスト・ルノワール', 'Pierre-Auguste Renoir', 'ルノワール',
        1841, 1919, 'west', array['impressionism']::text[],
        '人々の楽しげな姿を、柔らかな光と色で描いた印象派の画家です。', 'リモージュに生まれ、少年時代は陶磁器の絵付け職人として働きました。パリでモネらと出会い、印象派の仲間になります。

木漏れ日の中で踊る人々を描いた「ムーラン・ド・ラ・ギャレットの舞踏会」など、都市の余暇と幸福な時間を描きました。1880年代には輪郭をはっきりさせる描き方も試しています。

晩年はリウマチに苦しみながらも、筆を手に縛りつけて描き続けたといわれます。日本でも特に人気の高い画家の一人です。', 'https://ja.wikipedia.org/wiki/%E3%83%94%E3%82%A8%E3%83%BC%E3%83%AB%EF%BC%9D%E3%82%AA%E3%83%BC%E3%82%AE%E3%83%A5%E3%82%B9%E3%83%88%E3%83%BB%E3%83%AB%E3%83%8E%E3%83%AF%E3%83%BC%E3%83%AB')
