    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('エドガー・ドガ', 'Edgar Degas', 'ドガ',
        1834, 1917, 'west', array['impressionism']::text[],
        '踊り子や競馬、都市の人々を、意外な角度から切り取った画家です。', 'パリの銀行家の家に生まれ、アングルを尊敬して確かなデッサンを身につけました。印象派展には何度も参加しましたが、自身は「写実主義者」と名乗りました。

バレエの稽古場や舞台裏、カフェの人々を、写真や浮世絵を思わせる大胆なトリミングで描きました。パステルも多く用いています。

晩年は視力が衰え、彫刻も手がけました。「14歳の小さな踊り子」は、本物の布や髪を使った彫刻として知られます。', 'https://ja.wikipedia.org/wiki/%E3%82%A8%E3%83%89%E3%82%AC%E3%83%BC%E3%83%BB%E3%83%89%E3%82%AC')
