    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ベルト・モリゾ', 'Berthe Morisot', 'モリゾ',
        1841, 1895, 'west', array['impressionism']::text[],
        '家族や女性の日常を、軽やかな筆で描いた印象派の画家です。', 'フランスのブールジュに生まれ、姉とともに絵を学びました。マネと親しく交流し、その弟ウジェーヌと結婚しています。

1874年の第1回印象派展に参加した唯一の女性画家で、その後もほとんどの回に出品しました。

室内や庭で過ごす母と子、身支度をする女性など、当時の女性が見ていた世界を、すばやく軽い筆づかいで描きました。', 'https://ja.wikipedia.org/wiki/%E3%83%99%E3%83%AB%E3%83%88%E3%83%BB%E3%83%A2%E3%83%AA%E3%82%BE')
