insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('メアリー・カサット', 'Mary Cassatt', 'カサット',
        1844, 1926, 'west', array['impressionism']::text[],
        '母と子の情景を数多く描いた、アメリカ出身の印象派の画家です。', 'ペンシルベニアに生まれ、パリに移り住みました。ドガに誘われて印象派展に参加しています。

1890年にパリで開かれた日本の浮世絵展に感銘を受け、平らな色面と大胆な構図を取り入れた多色刷りの版画を制作しました。

アメリカの収集家に印象派の作品を紹介し、その作品がアメリカの美術館に入るきっかけもつくりました。', 'https://ja.wikipedia.org/wiki/%E3%83%A1%E3%82%A2%E3%83%AA%E3%83%BC%E3%83%BB%E3%82%AB%E3%82%B5%E3%83%83%E3%83%88')
