insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ポール・セザンヌ', 'Paul Cézanne', 'セザンヌ',
        1839, 1906, 'west', array['post-impressionism']::text[],
        '形と構成を突きつめ、「近代絵画の父」と呼ばれる画家です。', '南フランスのエクス＝アン＝プロヴァンスに生まれました。印象派展にも参加しましたが、やがて故郷に戻り、独自の探求を続けます。

りんごの静物やサント＝ヴィクトワール山を何度も描き、自然を円筒・球・円錐としてとらえる見方を示しました。複数の視点を一つの画面に組み合わせることもありました。

その試みはピカソやブラックのキュビスムに直接つながり、20世紀の美術に大きな影響を与えました。', 'https://ja.wikipedia.org/wiki/%E3%83%9D%E3%83%BC%E3%83%AB%E3%83%BB%E3%82%BB%E3%82%B6%E3%83%B3%E3%83%8C')
