insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フィンセント・ファン・ゴッホ', 'Vincent van Gogh', 'ゴッホ',
        1853, 1890, 'west', array['post-impressionism']::text[],
        '強い色と渦巻くような筆づかいで、感情を絵にしたオランダ出身の画家です。', 'オランダに牧師の子として生まれ、画商の店員や伝道師を経て、27歳ごろから本格的に絵を描き始めました。画家として活動したのは約10年です。

パリで印象派や浮世絵に出会って色が明るくなり、南フランスのアルルで「ひまわり」などを描きました。浮世絵を模写し、日本を理想の土地と考えていました。

生前に売れた絵はごくわずかでしたが、弟テオとの手紙からは、絵に込めた思いを詳しく知ることができます。37歳で亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A3%E3%83%B3%E3%82%BB%E3%83%B3%E3%83%88%E3%83%BB%E3%83%95%E3%82%A1%E3%83%B3%E3%83%BB%E3%82%B4%E3%83%83%E3%83%9B')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ポール・ゴーギャン', 'Paul Gauguin', 'ゴーギャン',
        1848, 1903, 'west', array['post-impressionism']::text[],
        '文明から離れた土地に理想を求め、鮮やかな色面で描いた画家です。', 'パリに生まれ、株式仲買人として働きながら絵を描き、のちに画家に専念しました。ブルターニュのポン＝タヴァンで若い画家たちと新しい描き方を探ります。

見たままの色ではなく、平らで強い色と輪郭線で画面を組み立てる「総合主義」を唱えました。アルルではゴッホと共同生活を送っています。

後半生は南太平洋のタヒチやマルキーズ諸島で暮らし、その地の人々や神話を描きました。', 'https://ja.wikipedia.org/wiki/%E3%83%9D%E3%83%BC%E3%83%AB%E3%83%BB%E3%82%B4%E3%83%BC%E3%82%AE%E3%83%A3%E3%83%B3')
