insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アンリ・ド・トゥールーズ＝ロートレック', 'Henri de Toulouse-Lautrec', 'ロートレック',
        1864, 1901, 'west', array['post-impressionism', 'art-nouveau']::text[],
        'モンマルトルの夜の世界と、そこで生きる人々を描いた画家です。', '南フランスの伯爵家に生まれました。少年時代の骨折がもとで足の成長が止まり、その後パリのモンマルトルに住みます。

キャバレー「ムーラン・ルージュ」の踊り子や歌手、娼館の女性たちを、すばやい線で生き生きと描きました。

浮世絵に学んだ大胆な構図と平らな色面のポスターは、ポスターを芸術に高めたものとして評価されています。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%B3%E3%83%AA%E3%83%BB%E3%83%89%E3%83%BB%E3%83%88%E3%82%A5%E3%83%BC%E3%83%AB%E3%83%BC%E3%82%BA%EF%BC%9D%E3%83%AD%E3%83%BC%E3%83%88%E3%83%AC%E3%83%83%E3%82%AF')
