insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('グスタフ・クリムト', 'Gustav Klimt', 'クリムト',
        1862, 1918, 'west', array['art-nouveau', 'symbolism']::text[],
        '金箔を用いた装飾的な画面で知られる、ウィーンの画家です。', 'ウィーン近郊に金工師の子として生まれ、工芸美術学校で学びました。はじめは劇場などの装飾画家として成功します。

1897年、保守的な美術界から離れて「ウィーン分離派」を結成し、初代会長になりました。「接吻」などの「黄金様式」の作品では、金箔と平らな文様の中に人物を浮かび上がらせています。

日本の工芸や琳派にも関心を寄せていたといわれます。エゴン・シーレら若い画家を支えたことでも知られます。', 'https://ja.wikipedia.org/wiki/%E3%82%B0%E3%82%B9%E3%82%BF%E3%83%95%E3%83%BB%E3%82%AF%E3%83%AA%E3%83%A0%E3%83%88')
