insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('エドヴァルド・ムンク', 'Edvard Munch', 'ムンク',
        1863, 1944, 'west', array['expressionism']::text[],
        '不安や孤独、愛と死といった心の内側を描いた、ノルウェーの画家です。', 'ノルウェーに生まれ、幼いころに母と姉を病気で亡くしました。パリやベルリンで活動し、晩年はオスロ近郊で過ごしました。

「叫び」をはじめとする作品を、人生の連作「生命のフリーズ」としてまとめようとしました。ゆがんだ線と強い色で、目に見える風景よりも感情を描いています。

その表現は、ドイツ表現主義の画家たちに大きな影響を与えました。', 'https://ja.wikipedia.org/wiki/%E3%82%A8%E3%83%89%E3%83%B4%E3%82%A1%E3%83%AB%E3%83%89%E3%83%BB%E3%83%A0%E3%83%B3%E3%82%AF')
