insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジョン・エヴァレット・ミレー', 'John Everett Millais', 'ミレイ',
        1829, 1896, 'west', array['pre-raphaelite']::text[],
        'ラファエル前派を結成した一人で、細密な描写で知られるイギリスの画家です。', 'サウサンプトンに生まれ、11歳でロイヤル・アカデミーの美術学校に入学した早熟の画家でした。

1848年、ロセッティやハントとラファエル前派兄弟団を結成しました。シェイクスピアの悲劇を描いた「オフィーリア」では、川辺の草花を実際に屋外で写生して描き込んでいます。

のちには一般に親しまれる作風に移り、ロイヤル・アカデミーの会長も務めました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A7%E3%83%B3%E3%83%BB%E3%82%A8%E3%83%B4%E3%82%A1%E3%83%AC%E3%83%83%E3%83%88%E3%83%BB%E3%83%9F%E3%83%AC%E3%83%BC')
