insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ダンテ・ゲイブリエル・ロセッティ', 'Dante Gabriel Rossetti', 'ロセッティ',
        1828, 1882, 'west', array['pre-raphaelite']::text[],
        '詩人でもあり、夢見るような女性像を描いたラファエル前派の画家です。', 'ロンドンにイタリア人の家庭で生まれました。詩人ダンテを敬愛し、その作品を主題にした絵を多く描いています。

ラファエル前派の結成に加わり、のちには豊かな髪と深い色をもつ女性の半身像を数多く描きました。

その作風はウィリアム・モリスやバーン＝ジョーンズらに受け継がれ、のちの象徴主義やアール・ヌーヴォーにもつながりました。', 'https://ja.wikipedia.org/wiki/%E3%83%80%E3%83%B3%E3%83%86%E3%83%BB%E3%82%B2%E3%82%A4%E3%83%96%E3%83%AA%E3%82%A8%E3%83%AB%E3%83%BB%E3%83%AD%E3%82%BB%E3%83%83%E3%83%86%E3%82%A3')
