insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('カスパー・ダーヴィト・フリードリヒ', 'Caspar David Friedrich', 'フリードリヒ',
        1774, 1840, 'west', array['romanticism']::text[],
        '自然の前にたたずむ人の姿を通して、崇高さや孤独を描いたドイツの画家です。', 'バルト海沿岸のグライフスヴァルトに生まれ、コペンハーゲンで学んだのち、ドレスデンで活動しました。

霧の海、月夜の浜辺、雪の森などを、静かで宗教的な気配とともに描きました。人物を後ろ姿で描くことが多く、見る人はその人物と同じ景色を見つめることになります。

死後は長く忘れられましたが、20世紀に入って再評価されました。', 'https://ja.wikipedia.org/wiki/%E3%82%AB%E3%82%B9%E3%83%91%E3%83%BC%E3%83%BB%E3%83%80%E3%83%BC%E3%83%B4%E3%82%A3%E3%83%88%E3%83%BB%E3%83%95%E3%83%AA%E3%83%BC%E3%83%89%E3%83%AA%E3%83%92')
