insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('黒田清輝', 'Kuroda Seiki', '黒田清輝',
        1866, 1924, 'japan', array['yoga-meiji']::text[],
        'フランスで学んだ明るい外光の表現を日本に伝え、近代洋画の基礎を築いた画家です。', '鹿児島に生まれ、法律を学ぶためにフランスへ留学しましたが、画家ラファエル・コランに学んで絵の道に進みました。

帰国後、明るい色調の画風で「新派」「紫派」と呼ばれ、白馬会を結成しました。東京美術学校に新設された西洋画科で教え、多くの後進を育てています。

代表作「湖畔」は、箱根の芦ノ湖を背景にうちわを持つ女性を描いた作品です。のちに貴族院議員も務めました。', 'https://ja.wikipedia.org/wiki/%E9%BB%92%E7%94%B0%E6%B8%85%E8%BC%9D')
