insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('高橋由一', 'Takahashi Yuichi', '高橋由一',
        1828, 1894, 'japan', array['yoga-meiji']::text[],
        '日本の近代洋画の開拓者とされる、幕末・明治の画家です。', '江戸の佐野藩士の家に生まれました。西洋の石版画を見てその写実性に驚き、洋画を志したといわれます。

イギリス人の画家ワーグマンに学び、油絵の技法を身につけました。代表作「鮭」は、吊るされた塩鮭を、身の質感までありのままに描いた作品です。

画塾「天絵楼（天絵社）」を開き、油絵の普及にも力を尽くしました。', 'https://ja.wikipedia.org/wiki/%E9%AB%98%E6%A9%8B%E7%94%B1%E4%B8%80')
