insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('青木繁', 'Aoki Shigeru', '青木繁',
        1882, 1911, 'japan', array['yoga-meiji']::text[],
        '神話や伝説に題材をとった浪漫的な作品で知られる、明治の洋画家です。', '福岡県久留米に生まれ、東京美術学校で黒田清輝らに学びました。

千葉県布良（めら）の海辺で描いた「海の幸」は、漁から戻る男たちを力強く描いた作品で、日本の近代洋画を代表する一点とされます。「わだつみのいろこの宮」など、日本神話を描いた作品もあります。

その後は不遇のうちに各地を放浪し、28歳で亡くなりました。', 'https://ja.wikipedia.org/wiki/%E9%9D%92%E6%9C%A8%E7%B9%81')
