insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('上村松園', 'Uemura Shōen', '上村松園',
        1875, 1949, 'japan', array['nihonga']::text[],
        '気品ある女性像を描き続けた、京都の日本画家です。', '京都の葉茶屋に生まれ、鈴木松年、幸野楳嶺、竹内栖鳳に学びました。女性が画家として生きることが難しかった時代に、若くして展覧会で認められます。

「一点の卑俗なところもなく、清澄な感じのする香高い珠玉のような絵」を理想とし、能や古典に取材した女性像を描きました。

1948年、女性として初めて文化勲章を受けました。', 'https://ja.wikipedia.org/wiki/%E4%B8%8A%E6%9D%91%E6%9D%BE%E5%9C%92')
