insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('菱田春草', 'Hishida Shunsō', '菱田春草',
        1874, 1911, 'japan', array['nihonga']::text[],
        '輪郭線を使わない新しい表現に挑んだ、明治の日本画家です。', '長野県飯田に生まれ、東京美術学校で岡倉天心や橋本雅邦に学びました。横山大観とともに日本美術院の創立に参加しています。

線を使わずに色のぼかしで空気や光を表そうとした試みは、当時「朦朧体」と批判されましたが、日本画の可能性を広げました。

代表作「黒き猫」は、柏の木にうずくまる黒猫を描いた作品です。36歳の若さで亡くなりました。', 'https://ja.wikipedia.org/wiki/%E8%8F%B1%E7%94%B0%E6%98%A5%E8%8D%89')
