insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('酒井抱一', 'Sakai Hōitsu', '抱一',
        1761, 1829, 'japan', array['rinpa']::text[],
        '尾形光琳に私淑し、江戸で琳派を再興した画家です。', '姫路藩主の酒井家に生まれ、俳諧や狂歌、浮世絵にも親しみました。のちに出家しています。

光琳の百回忌に遺作展を開き、作品集を出版して光琳の名を広めました。光琳の「風神雷神図屏風」の裏には、抱一の「夏秋草図屏風」が描かれていました。

江戸の洒脱な感覚を生かした草花図で、「江戸琳派」と呼ばれる流れを生み、鈴木其一らに受け継がれました。', 'https://ja.wikipedia.org/wiki/%E9%85%92%E4%BA%95%E6%8A%B1%E4%B8%80')
