insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('与謝蕪村', 'Yosa Buson', '蕪村',
        1716, 1784, 'japan', array['nanga']::text[],
        '俳人としても画家としても大きな足跡を残した、江戸時代中期の文人です。', '摂津国（いまの大阪市）に生まれ、江戸で俳諧を学んだのち、各地を旅して京都に落ち着きました。

中国の文人画に学んだ南画（文人画）で、池大雅と合作した「十便十宜図」が知られます。俳句に絵を添えた「俳画」も確立しました。

「菜の花や月は東に日は西に」など、絵のような情景を詠んだ句でも知られます。晩年の「夜色楼台図」（国宝）では、雪の夜の京の町並みを墨の濃淡で詩情豊かに描きました。', 'https://ja.wikipedia.org/wiki/%E4%B8%8E%E8%AC%9D%E8%95%AA%E6%9D%91')
