insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('池大雅', 'Ike no Taiga', '池大雅',
        1723, 1776, 'japan', array['nanga']::text[],
        '日本の南画（文人画）を大成した、江戸時代中期の画家・書家です。', '京都に生まれ、幼いころから書の才能を示しました。

中国の文人画を学びながら、各地の山に登って実際の風景を写し、明るくのびやかな独自の山水画をつくりあげました。富士山・白山・立山に登ったことから「三岳道者」とも号しています。

与謝蕪村との合作「十便十宜図」（国宝）では、大雅が「十便」を描いています。書家としても名高く、妻の玉瀾も画家として知られました。', 'https://ja.wikipedia.org/wiki/%E6%B1%A0%E5%A4%A7%E9%9B%85')
