insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('パブロ・ピカソ', 'Pablo Picasso', 'ピカソ',
        1881, 1973, 'west', array['cubism']::text[],
        'キュビスムを生み出し、生涯に何度も作風を変えた20世紀を代表する画家です。', 'スペインのマラガに生まれ、パリを拠点に活動しました。青を基調とした「青の時代」、淡い色調の「バラ色の時代」を経て、1907年に「アヴィニョンの娘たち」を描きます。

ジョルジュ・ブラックとともに、ものを複数の視点から見た形に分解して組み立て直すキュビスムを展開しました。スペイン内戦の空爆に抗議した「ゲルニカ」も代表作です。

晩年まで絵画・彫刻・陶芸・版画と表現を広げ続け、生涯の作品数は数万点にのぼるといわれます。', 'https://ja.wikipedia.org/wiki/%E3%83%91%E3%83%96%E3%83%AD%E3%83%BB%E3%83%94%E3%82%AB%E3%82%BD')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジョルジュ・ブラック', 'Georges Braque', 'ブラック',
        1882, 1963, 'west', array['cubism']::text[],
        'ピカソとともにキュビスムを切り開いたフランスの画家です。', 'パリ近郊に生まれ、はじめはフォーヴィスムの画家として活動しました。セザンヌの作品に強い影響を受けています。

1908年ごろからピカソと密に協力して、キュビスムを発展させました。新聞紙や壁紙を画面に貼る「パピエ・コレ」を始めたのもブラックです。

晩年は鳥やアトリエを主題にした静かな連作を描き、ルーヴル美術館の天井画も手がけました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A7%E3%83%AB%E3%82%B8%E3%83%A5%E3%83%BB%E3%83%96%E3%83%A9%E3%83%83%E3%82%AF')
