insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('マルセル・デュシャン', 'Marcel Duchamp', 'デュシャン',
        1887, 1968, 'west', array['dada']::text[],
        '既製品を「作品」として示し、芸術とは何かを問い直したフランス出身の美術家です。', 'フランスのノルマンディーに生まれ、はじめはキュビスムの影響を受けた絵を描いていました。

1917年、男性用小便器に署名して「泉」と名づけ、展覧会に出品しようとしました。作品を「手で作る」ことよりも「選ぶ」こと、考えることを重んじたその姿勢は、のちのコンセプチュアル・アートにつながります。

晩年はチェスに打ち込み、美術をやめたと思われていましたが、死後に20年かけた秘密の作品「遺作」が公開されました。', 'https://ja.wikipedia.org/wiki/%E3%83%9E%E3%83%AB%E3%82%BB%E3%83%AB%E3%83%BB%E3%83%87%E3%83%A5%E3%82%B7%E3%83%A3%E3%83%B3')
