insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('サルバドール・ダリ', 'Salvador Dalí', 'ダリ',
        1904, 1989, 'west', array['surrealism']::text[],
        '溶ける時計などの奇妙な夢の光景を、緻密な写実で描いたスペインの画家です。', 'カタルーニャ地方のフィゲラスに生まれ、マドリードで学びました。パリでシュルレアリスムのグループに加わります。

現実にはありえない光景を、写真のように正確に描くことで、夢の中のような不安と驚きを生み出しました。代表作に「記憶の固執」があります。

上向きにはねた口ひげと奇抜なふるまいでも知られ、映画や広告、宝飾品のデザインまで手がけました。故郷フィゲラスにはダリ劇場美術館があります。', 'https://ja.wikipedia.org/wiki/%E3%82%B5%E3%83%AB%E3%83%90%E3%83%89%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%80%E3%83%AA')
