    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ルネ・マグリット', 'René Magritte', 'マグリット',
        1898, 1967, 'west', array['surrealism']::text[],
        '見慣れたものを意外な組み合わせで描き、見る人の思い込みを揺さぶったベルギーの画家です。', 'ベルギーに生まれ、ブリュッセルで学びました。広告や壁紙のデザインの仕事もしています。

パイプの絵に「これはパイプではない」と書き添えた作品など、言葉とイメージ、現実と絵の関係を問いかける作品で知られます。

空に浮かぶ岩、昼の空と夜の街が同居する「光の帝国」など、静かで明快な描き方だからこそ不思議さが際立ちます。その発想は、のちの広告やデザインにも大きな影響を与えました。', 'https://ja.wikipedia.org/wiki/%E3%83%AB%E3%83%8D%E3%83%BB%E3%83%9E%E3%82%B0%E3%83%AA%E3%83%83%E3%83%88')
