    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジャクソン・ポロック', 'Jackson Pollock', 'ポロック',
        1912, 1956, 'west', array['abstract-expressionism']::text[],
        '床に広げたキャンバスに絵の具を滴らせる描き方で、抽象表現主義を代表するアメリカの画家です。', 'ワイオミング州に生まれ、ニューヨークで学びました。

1947年ごろから、キャンバスを床に置き、棒や缶から絵の具を垂らしたり振りかけたりする「ドリッピング」の技法で、画面全体を均一に覆う作品を描きました。描く行為そのものが作品になるという考えは「アクション・ペインティング」と呼ばれました。

中心も上下もない画面は、それまでの「窓のような絵」の考え方を大きく変え、ニューヨークを戦後美術の中心に押し上げる力の一つになりました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A3%E3%82%AF%E3%82%BD%E3%83%B3%E3%83%BB%E3%83%9D%E3%83%AD%E3%83%83%E3%82%AF')
