    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('マーク・ロスコ', 'Mark Rothko', 'ロスコ',
        1903, 1970, 'west', array['abstract-expressionism']::text[],
        '大きな画面に、にじむような色の長方形を浮かべた抽象表現主義の画家です。', 'ロシア帝国（いまのラトビア）に生まれ、10歳でアメリカに移住しました。

1950年ごろから、境界のぼやけた色面を重ねた大きな絵を描き、見る人が色に包まれるような体験をめざしました。千葉県のDIC川村記念美術館には、ロスコの作品だけを展示する部屋がありました。

晩年に依頼を受けたヒューストンの礼拝堂「ロスコ・チャペル」は、自作だけを掛けた空間として、死の翌年に完成しました。', 'https://ja.wikipedia.org/wiki/%E3%83%9E%E3%83%BC%E3%82%AF%E3%83%BB%E3%83%AD%E3%82%B9%E3%82%B3')
