insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アンディ・ウォーホル', 'Andy Warhol', 'ウォーホル',
        1928, 1987, 'west', array['pop-art']::text[],
        '大量生産の商品やスターの顔をシルクスクリーンで繰り返し刷った、ポップアートの代表的な美術家です。', 'ピッツバーグに生まれ、ニューヨークで商業イラストレーターとして成功しました。

キャンベル・スープの缶やマリリン・モンローの顔を、版画の技法で何枚も並べ、芸術と大量消費社会の境界を問い直しました。スタジオ「ファクトリー」では映画も制作しています。

「誰でも15分間は有名になれる」という言葉でも知られ、名声やメディアそのものを作品の主題にしました。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%B3%E3%83%87%E3%82%A3%E3%83%BB%E3%82%A6%E3%82%A9%E3%83%BC%E3%83%9B%E3%83%AB')
