insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('吉原治良', 'Yoshihara Jirō', '吉原治良',
        1905, 1972, 'japan', array['gutai']::text[],
        '「人の真似をするな」と若い作家を励まし、具体美術協会を率いた画家です。', '大阪に生まれ、家業の油問屋を経営しながら絵を描きました。

1954年、兵庫県芦屋で若い美術家たちと具体美術協会を結成しました。屋外での展覧会や舞台での発表など、前例のない表現を次々に後押ししました。晩年は円を描いた作品で知られます。

具体の活動は海外でも紹介され、戦後日本の前衛美術を代表する動きとして、いま世界的に再評価されています。', 'https://ja.wikipedia.org/wiki/%E5%90%89%E5%8E%9F%E6%B2%BB%E8%89%AF')
