insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('白髪一雄', 'Shiraga Kazuo', '白髪一雄',
        1924, 2008, 'japan', array['gutai']::text[],
        '天井から吊ったロープにつかまり、足で絵の具を広げて描いた具体美術協会の画家です。', '兵庫県尼崎に生まれ、京都で日本画を学んだのち油彩に転じました。

床に置いたキャンバスの上で、足を使って全身で描く「フット・ペインティング」で知られます。泥の中で体をぶつける「泥に挑む」というパフォーマンスも行いました。

天台宗の僧侶としての修行も積み、水滸伝の豪傑にちなんだ題名の作品群でも知られます。具体の活動は海外でも高く評価され、晩年まで大画面に挑み続けました。', 'https://ja.wikipedia.org/wiki/%E7%99%BD%E9%AB%AA%E4%B8%80%E9%9B%84')
